import{_ as t,o,c as a,a4 as r}from"./chunks/framework.DpieW3qv.js";const m=JSON.parse('{"title":"Wireframe Format","description":"","frontmatter":{"title":"Wireframe Format"},"headers":[],"relativePath":"excel/wireframe-format.md","filePath":"excel/wireframe-format.md","lastUpdated":null}'),d={name:"excel/wireframe-format.md"};function s(n,e,i,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="wireframe-format" tabindex="-1">Wireframe format <a class="header-anchor" href="#wireframe-format" aria-label="Permalink to &quot;Wireframe format&quot;">​</a></h1><p>This page defines the wireframe format the CLI expects. Use it when preparing or editing the Excel file.</p><h2 id="supported-excel-formats" tabindex="-1">Supported Excel formats <a class="header-anchor" href="#supported-excel-formats" aria-label="Permalink to &quot;Supported Excel formats&quot;">​</a></h2><p>The system auto-detects the format based on column headers:</p><table tabindex="0"><thead><tr><th>Format</th><th>When to use</th><th>Detection</th></tr></thead><tbody><tr><td><strong>CONVERTED</strong></td><td>Standard (recommended)</td><td>Has REFRESH_NAME, REFRESH_DATE, ACTION, ASSET_TYPE, SITE_LOCATION</td></tr><tr><td><strong>BANNER</strong></td><td>Legacy LOFT format</td><td>Has WEB_PROD_CODED, DEVICE with date patterns</td></tr><tr><td><strong>FLAT_TIMED</strong></td><td>Timed refreshes</td><td>Has REFRESH_DATE, START_DATETIME, ACTION</td></tr></tbody></table><h2 id="converted-format-recommended" tabindex="-1">CONVERTED format (recommended) <a class="header-anchor" href="#converted-format-recommended" aria-label="Permalink to &quot;CONVERTED format (recommended)&quot;">​</a></h2><h3 id="required-columns" tabindex="-1">Required columns <a class="header-anchor" href="#required-columns" aria-label="Permalink to &quot;Required columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>REFRESH NAME</code></td><td>Name of the refresh</td><td>&quot;1/26 Winter Sale&quot;</td></tr><tr><td><code>DATE</code> or <code>REFRESH DATE</code></td><td>When content goes live</td><td>1/26/2026</td></tr><tr><td><code>ACTION</code></td><td>What to do</td><td>LAUNCH, NO_CHANGE, REMOVE</td></tr><tr><td><code>SITE LOCATION</code></td><td>Where on site</td><td>HOMEPAGE, PPH, POPUP</td></tr><tr><td><code>ASSET TYPE</code></td><td>Content type</td><td>HOMEPAGE, PPH, COUPONS</td></tr></tbody></table><h3 id="optional-columns" tabindex="-1">Optional columns <a class="header-anchor" href="#optional-columns" aria-label="Permalink to &quot;Optional columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Aliases</th><th>Description</th></tr></thead><tbody><tr><td><code>ZONE</code></td><td>PLACEMENT, PLACEMENT ZONE</td><td>Zone within asset type</td></tr><tr><td><code>COPY</code></td><td>MESSAGE, COPY_MESSAGE, DISCLAIMER</td><td>Marketing copy text</td></tr><tr><td><code>DESTINATION ID</code></td><td>—</td><td>Link destination (category ID or URL)</td></tr><tr><td><code>IPID</code></td><td>—</td><td>Analytics tracking ID</td></tr><tr><td><code>ALT TEXT</code></td><td>—</td><td>Image accessibility text</td></tr><tr><td><code>TIME</code></td><td>START_TIME, TIME (ET)</td><td>Refresh time</td></tr><tr><td><code>START_DATETIME</code> / <code>END_DATETIME</code></td><td>—</td><td>Live window (when campaign is live); drives status <strong>Date/time</strong> display in local time</td></tr><tr><td><code>ORDER</code></td><td>ITEM #, ITEM_ORDER</td><td>Item order within zone</td></tr><tr><td><code>NOTES</code></td><td>—</td><td>Internal notes</td></tr></tbody></table><h3 id="column-name-aliases" tabindex="-1">Column name aliases <a class="header-anchor" href="#column-name-aliases" aria-label="Permalink to &quot;Column name aliases&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You can use</th><th>Recognized as</th></tr></thead><tbody><tr><td>REFRESH NAME, PROJECT SUMMARY, INITIATIVE</td><td>REFRESH_NAME</td></tr><tr><td>DATE, REFRESH DATE, REFRESH_DATE</td><td>REFRESH_DATE</td></tr><tr><td>ACTION, LAUNCH/REMOVE</td><td>ACTION</td></tr><tr><td>COPY, MESSAGE, PLACEMENT NOTES/PPH MESSAGE</td><td>COPY_MESSAGE</td></tr><tr><td>ZONE, PLACEMENT, PLACEMENT ZONE</td><td>ZONE</td></tr><tr><td>LINK/TRACKING, LINK, TRACKING</td><td>Link (parsed for destination)</td></tr></tbody></table><h2 id="sheet-structure-parent-child-rows" tabindex="-1">Sheet structure: parent-child rows <a class="header-anchor" href="#sheet-structure-parent-child-rows" aria-label="Permalink to &quot;Sheet structure: parent-child rows&quot;">​</a></h2><ul><li><strong>Parent row:</strong> Has REFRESH NAME and DATE; no ASSET TYPE.</li><li><strong>Child rows:</strong> Have ACTION, ASSET TYPE, ZONE; they inherit date from the parent.</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REFRESH NAME     │ DATE      │ ACTION │ ASSET TYPE │ ZONE</span></span>
<span class="line"><span>1/26 Winter Sale │ 1/26/2026 │        │            │        ← Parent</span></span>
<span class="line"><span>                 │           │ LAUNCH │ HOMEPAGE   │ HP_HERO  ← Child</span></span>
<span class="line"><span>                 │           │ LAUNCH │ HOMEPAGE   │ HP_2T    ← Child</span></span>
<span class="line"><span>                 │           │ NO_CHANGE │ PPH     │ PPH      ← Child</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="action-types" tabindex="-1">Action types <a class="header-anchor" href="#action-types" aria-label="Permalink to &quot;Action types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th><th>System behavior</th></tr></thead><tbody><tr><td><strong>LAUNCH</strong></td><td>New content</td><td>Generates new HTML, registers in asset registry</td></tr><tr><td><strong>UPDATE</strong></td><td>Modify existing</td><td>Re-renders HTML, syncs updated content to SFCC</td></tr><tr><td><strong>REMOVE</strong></td><td>Delete content</td><td>Unregisters zone, deletes from SFCC</td></tr><tr><td><strong>NO_CHANGE</strong></td><td>Same as before</td><td>Reuses asset from registry, no new files</td></tr></tbody></table><h2 id="example-one-row-→-one-asset" tabindex="-1">Example: one row → one asset <a class="header-anchor" href="#example-one-row-→-one-asset" aria-label="Permalink to &quot;Example: one row → one asset&quot;">​</a></h2><p>A single child row with <code>ACTION=LAUNCH</code>, <code>ASSET_TYPE=PPH</code>, <code>ZONE=PPH</code>, <code>COPY=50% off winter</code> becomes one content asset in the refresh JSON under <code>assetsByType.PPH</code>. After build, it appears in the PPH template output and in the OCAPI payload for that slot.</p><h2 id="example-rows-→-json-structure" tabindex="-1">Example: rows → JSON structure <a class="header-anchor" href="#example-rows-→-json-structure" aria-label="Permalink to &quot;Example: rows → JSON structure&quot;">​</a></h2><p>Here are two sample Excel rows (child rows under a parent with REFRESH NAME and DATE) and the shape of the parsed refresh JSON they produce.</p><p><strong>Excel rows (CONVERTED format):</strong></p><table tabindex="0"><thead><tr><th>REFRESH NAME</th><th>DATE</th><th>ACTION</th><th>ASSET TYPE</th><th>ZONE</th><th>COPY</th><th>DESTINATION ID</th></tr></thead><tbody><tr><td>1/26 Winter Sale</td><td>1/26/2026</td><td>LAUNCH</td><td>HOMEPAGE</td><td>HP_HERO</td><td>50% off winter</td><td>/sale/winter</td></tr><tr><td>1/26 Winter Sale</td><td>1/26/2026</td><td>LAUNCH</td><td>PPH</td><td>PPH</td><td>Free shipping</td><td>/shipping</td></tr></tbody></table><p><strong>Resulting structure in <code>refresh.json</code> (simplified):</strong></p><ul><li><code>campaign.refresh.date</code> = <code>&quot;2026-01-26&quot;</code>, <code>campaign.refresh.name</code> = from parent row.</li><li><code>assetsByType.HOMEPAGE.zones</code> = one zone object with <code>zone: &quot;HP_HERO&quot;</code>, <code>items: [{ action: &quot;LAUNCH&quot;, copy: &quot;50% off winter&quot;, destination: &quot;/sale/winter&quot;, ... }]</code>.</li><li><code>assetsByType.PPH.zones</code> = one zone with <code>zone: &quot;PPH&quot;</code>, <code>items: [{ action: &quot;LAUNCH&quot;, copy: &quot;Free shipping&quot;, destination: &quot;/shipping&quot;, ... }]</code>.</li></ul><p>After <strong>make build</strong>, each zone gets rendered HTML and an asset ID (and IPID for LAUNCH). The OCAPI payload then includes these assets and their slot bindings.</p><h3 id="dates-and-times-excel-vs-status-board" tabindex="-1">Dates and times: Excel vs status board <a class="header-anchor" href="#dates-and-times-excel-vs-status-board" aria-label="Permalink to &quot;Dates and times: Excel vs status board&quot;">​</a></h3><p>The status board shows a <strong>Date/time</strong> column and a <strong>Name</strong> column. They come from different Excel columns and can look different if your sheet uses date prefixes in the name or midnight UTC times.</p><table tabindex="0"><thead><tr><th>Source</th><th>Excel column(s)</th><th>What it controls</th></tr></thead><tbody><tr><td><strong>Folder / row date</strong></td><td><code>DATE</code> / <code>REFRESH DATE</code></td><td>The refresh’s logical date: folder path (<code>refreshes/YYYY-MM-DD/r1</code>) and row ordering on the status board.</td></tr><tr><td><strong>Name</strong></td><td><code>REFRESH NAME</code></td><td>The <strong>Name</strong> column on the status board (e.g. <code>&quot;2/20: $39 FP PANTS / STYLE EVENT EP 40&quot;</code>). The prefix <code>2/20:</code> is just text.</td></tr><tr><td><strong>Date/time column</strong></td><td><code>START_DATETIME</code>, <code>END_DATETIME</code> (optional)</td><td>The <strong>live window</strong> (when the campaign is “live” on the site). Converted to local time for display (e.g. <code>2/19 7pm – 2/19 7pm</code>).</td></tr></tbody></table><p>So:</p><ul><li><strong>Name</strong> can include a date like <code>2/20:</code> (the “go live” day in the label). That does <strong>not</strong> set the live window.</li><li><strong>Date/time</strong> on the board = <code>startTime</code>–<code>endTime</code> from the refresh, shown in <strong>local time</strong>. If you leave start/end blank, they are inferred from the refresh name (e.g. <code>@3PM</code>) or from the next refresh’s start; if you use midnight UTC (<code>2026-02-20T00:00:00.000Z</code>), they will show as the <strong>previous calendar day</strong> in US timezones (e.g. 2/19 4pm or 7pm depending on zone).</li></ul><p>To have the status <strong>Date/time</strong> match the date in the <strong>Name</strong> (e.g. “2/20” in both):</p><ul><li>Use <strong>START_DATETIME</strong> / <strong>END_DATETIME</strong> (or the <strong>TIME</strong> column where supported) with the intended go-live time in the correct timezone (e.g. 7pm ET on 2/20), so that the displayed window lines up with the date in the name.</li></ul><p><strong>Multi-day windows:</strong> A refresh can run across several days (e.g. &quot;2/20 60% off&quot; live from 2/20–2/22). Put the actual start and end datetimes in <strong>START_DATETIME</strong> and <strong>END_DATETIME</strong> (full date+time, e.g. from Excel or ISO). The parser uses those values from the file as-is, so the status <strong>Date/time</strong> column will show the correct range (e.g. <code>2/20 7pm – 2/22 11pm</code> in local time).</p><h3 id="when-the-sheet-has-dates-properly-entered-sfcc-format" tabindex="-1">When the sheet has dates properly entered (SFCC format) <a class="header-anchor" href="#when-the-sheet-has-dates-properly-entered-sfcc-format" aria-label="Permalink to &quot;When the sheet has dates properly entered (SFCC format)&quot;">​</a></h3><p>If the sheet has <strong>REFRESH_DATE</strong> plus <strong>START_DATETIME</strong> / <strong>END_DATETIME</strong> (or full datetime cells), the pipeline keeps them in the format SFCC expects:</p><ol><li><strong>Parser</strong> — Reads the sheet and normalizes to <strong>ISO 8601</strong> (e.g. <code>2026-02-19T19:00:00.000Z</code>). Time-only values (e.g. <code>7:00 PM</code>) are combined with REFRESH_DATE; full datetimes (e.g. Excel date+time or ISO strings) are used as-is. Result is stored in <code>refresh.json</code> as <code>campaign.refresh.startTime</code> and <code>endTime</code>.</li><li><strong>Build / OCAPI</strong> — When building the campaign and slot configurations, those same ISO strings are passed through as <code>start_date</code> and <code>end_date</code> on the campaign and on each slot’s <code>schedule</code>. No extra conversion is done.</li><li><strong>SFCC</strong> — OCAPI expects <code>schedule.start_date</code> and <code>schedule.end_date</code> in <strong>ISO 8601</strong>. The payload sends them in that form, so SFCC receives exactly what the sheet specified (in UTC).</li></ol><p>So: enter dates (and, if you want a specific go-live time, <strong>START_DATETIME</strong> / <strong>END_DATETIME</strong> or a full datetime). The system keeps everything as ISO 8601 from the sheet through to SFCC. Times in the sheet (e.g. <code>19:00</code> or <code>7:00 PM</code>) are interpreted as UTC when combined with the date unless you use a full datetime that already carries timezone (e.g. an ISO string with <code>Z</code> or offset).</p><p><strong>Current setup:</strong> If you use the conversion script (original → CONVERTED), when the original has no time the script now writes default <strong>START_DATETIME</strong> <code>19:00</code> and <strong>END_DATETIME</strong> <code>23:59</code> into the CONVERTED file so it is already in proper form. Use that CONVERTED file as your source (<code>activeSource: local</code>); the next pull/build will produce ISO 8601 through to SFCC. You can still override by putting times in the original (e.g. in the refresh label or in time columns) or by editing the CONVERTED file.</p><h2 id="site-locations-and-zones" tabindex="-1">Site locations and zones <a class="header-anchor" href="#site-locations-and-zones" aria-label="Permalink to &quot;Site locations and zones&quot;">​</a></h2><p>Asset types (HOMEPAGE, PPH, POPUP, COUPONS, PLP_HEADER, etc.) and their zones are defined in config. Homepage zones (e.g. HP_TOP_BANNER, HP_2T) are often auto-merged from Excel names like &quot;TOP BANNER&quot; or &quot;SLOT 1&quot;. See <a href="/ocapi-docs.github.io/concepts/content-model.html">Slots, Assets, Zones</a> and <a href="/ocapi-docs.github.io/concepts/content-model.html">Asset Types (data flow)</a>.</p><h2 id="validation-checklist" tabindex="-1">Validation checklist <a class="header-anchor" href="#validation-checklist" aria-label="Permalink to &quot;Validation checklist&quot;">​</a></h2><p>Before saving your wireframe:</p><ul><li>[ ] All required columns present (REFRESH NAME, DATE, ACTION, ASSET TYPE, SITE LOCATION or SITE_LOCATION — both accepted)</li><li>[ ] Actions are valid (LAUNCH, UPDATE, REMOVE, NO_CHANGE)</li><li>[ ] Dates in a format Excel parses (e.g. M/D/YYYY)</li><li>[ ] No empty rows breaking parent-child grouping</li><li>[ ] IPIDs follow naming convention (see <a href="./validation-and-fixes.html">Validation and fixes</a>)</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./how-changeouts-flow.html">How changeouts flow</a> — Commands to run</li><li><a href="./validation-and-fixes.html">Validation and fixes</a> — Errors and how to fix in Excel</li><li><a href="/ocapi-docs.github.io/guides/wireframe.html">Wireframe Guide</a> — Full wireframe reference (IPID format, destination types, multiple sheets)</li></ul>`,46)])])}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
